import { isFunction } from "./isFunction";
import { isString } from "./isString";
export function hasKey(obj, key) {
    return key in obj;
}
export function hasStringAtKey(obj, key) {
    return hasKey(obj, key) && isString(obj[key]);
}
export function hasValueAtKey(obj, key, value) {
    return hasKey(obj, key) && obj[key] === value;
}
export function hasFunctionAtKey(obj, key) {
    return hasKey(obj, key) && isFunction(obj[key]);
}
